import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        m = int(next(iterator))
    except StopIteration:
        return

    balance = [0] * (n + 1)

    for _ in range(m):
        a = int(next(iterator))
        b = int(next(iterator))
        c = int(next(iterator))
        balance[a] -= c
        balance[b] += c

    debtors = []
    creditors = []

    for i in range(1, n + 1):
        if balance[i] < 0:
            debtors.append(-balance[i])
        elif balance[i] > 0:
            creditors.append(balance[i])

    debtors.sort(reverse=True)
    creditors.sort(reverse=True)

    total_debt = 0
    i = 0
    j = 0

    while i < len(debtors) and j < len(creditors):
        total_debt += min(debtors[i], creditors[j])
        if debtors[i] == creditors[j]:
            i += 1
            j += 1
        elif debtors[i] < creditors[j]:
            i += 1
        else:
            j += 1

    print(total_debt)

if __name__ == "__main__":
    solve()

